void deleteIndexFiles(Directory directory, Collection<SnapshotMetaData> snapshotMetaDataList, long generationNumber) {
    // List of all index commits in the directory.
    List<IndexCommit> indexCommits = DirectoryReader.listCommits(directory);
    // Dictionary mapping the generation number to the index commit.
    Map<Long, IndexCommit> generationNumberToIndexCommit = new HashMap<>();
    for (IndexCommit indexCommit : indexCommits) {
        generationNumberToIndexCommit.put(indexCommit.getGeneration(), indexCommit);
    }
    // Only delete the index files for the given generation number.
    IndexCommit indexCommit = generationNumberToIndexCommit.get(generationNumber);
    if (indexCommit != null) {
        deleteIndexFiles(directory, snapshotMetaDataList, indexCommit);
    }
}

