void insertBefore(Bucket bucket) {
    // Insert the current bucket before the given bucket
    // Complexity: O(1)

    // Get the index of the given bucket
    int bucketIndex = bucket.getIndex();

    // Get the index of the current bucket
    int currentBucketIndex = this.getIndex();

    // If the given bucket is not in the data structure, throw an exception
    if (bucketIndex < 0) {
        throw new IllegalArgumentException("Bucket is not in the data structure");
    }

    // If the current bucket is not in the data structure, throw an exception
    if (currentBucketIndex < 0) {
        throw new IllegalArgumentException("Current bucket is not in the data structure");
    }

    // If the given bucket is the first bucket in the data structure, insert the current bucket at the beginning
    if (bucketIndex == 0) {
        // Insert the current bucket at the beginning of the data structure
        data.add(0, currentBucketIndex);
        // Update the references of all buckets in the data structure
        for (int i = 0; i < data.size(); i++) {
            int ref = data.get(i);
            if (ref >= 0) {
                buckets[ref].setPrevious(currentBucketIndex);
            }
        }
        // Set the previous reference of the current bucket to -1
        currentBucket.setPrevious(-1);
        // Set the next reference of the given bucket to the current bucket
        bucket.setNext(currentBucketIndex);
    }

    // If the given bucket is not the first bucket in the data structure, insert the current bucket after the given bucket
    else {
        // Get the previous bucket of the given bucket
        Bucket previousBucket = buckets[bucket.getPrevious()];
        // Insert the current bucket after the given bucket
        previousBucket.setNext(currentBucketIndex);
        // Update the references of all buckets in the data structure
        for (int i = 0; i < data.size(); i++) {
            int ref = data.get(i);
            if (ref >= 0) {
                buckets[ref].setPrevious(currentBucketIndex);
            }
        }
        // Set the previous reference of the current bucket to the given bucket
        currentBucket.setPrevious(bucketIndex);
        // Set the next reference of the given bucket to the current bucket
        bucket.setNext(currentBucketIndex);
    }
}

