    // Insert this bucket in the data structure before the bucket parameter
    // First, find the bucket's position in the data structure
    int bucketPosition = getPositionOfBucket(bucket);
    // If the bucket is not found, throw an exception
    if (bucketPosition == -1) {
        throw new IllegalArgumentException("Bucket not found");
    }
    // Insert this bucket in the data structure before the bucket's position
    data.add(bucketPosition, this);
