public void insertBefore(Bucket bucket) {
    // Check if the given bucket is null
    if (bucket == null) {
        throw new IllegalArgumentException("Bucket cannot be null");
    }

    // Check if this bucket is already in the data structure
    if (contains(bucket)) {
        throw new IllegalStateException("Bucket is already in the data structure");
    }

    // Check if the given bucket has already been inserted in the data structure
    if (bucket.contains(this)) {
        throw new IllegalStateException("Bucket has already been inserted");
    }

    // Insert the given bucket in the data structure before this bucket
