public List<Integer> computeLowerBounds(List<K> keys) {
    if (keys.isEmpty()) {
        return Collections.emptyList();
    }

    // Sort the keys in ascending order
    keys.sort(Comparator.naturalOrder());

    // Initialize the list of lower bounds
    List<Integer> lowerBounds = new ArrayList<>(keys.size());

    // Compute the lower bound for each key
    for (int i = 1; i < keys.size(); i++) {
        while (i > 0 && keys.get(i).compareTo(keys.get(i - 1)) == 0) {
            i--;
        }
        lowerBounds.add(i);
    }

    return lowerBounds;
}

