private static String unescapeId(String input) {
    if (input == null || input.isEmpty()) {
        return input;
    }
    StringBuilder output = new StringBuilder();
    int i = 0;
    while (i < input.length()) {
        char c = input.charAt(i);
        if (c != '\\') {
            output.append(c);
            i++;
            continue;
        }
        i++;
        if (i >= input.length()) {
            throw new IllegalArgumentException("Invalid escape sequence at the end of the string");
        }
        c = input.charAt(i++);
        switch (c) {
            case 'n':
                output.append('\n');
                break;
            case 'r':
                output.append('\r');
                break;
            case 't':
                output.append('\t');
                break;
            case '"':
                output.append('"');
                break;
            case '\\':
                output.append('\\');
                break;
            default:
                throw new IllegalArgumentException("Invalid escape sequence: \\" + c);
        }
    }
    return output.toString();
}

public String unescapeId(String input) {
    return input.replaceAll("\\\\.", ".");
}

public String unescapeId(String input) {
    return input.replaceAll("\\\\([^\\\\])", "$1");
}

public String unescapeId(String input) {
    // Unescape any backslash escapes in the input string
    String unescaped = input.replaceAll("\\\\", "");
    // Check if the unescaped string is a valid DOT identifier
    boolean validId = Pattern.matches("[a-zA-Z_][a-zA-Z0-9_]*", unescaped);
    if (!validId) {
        throw new IllegalArgumentException("Invalid DOT identifier: " + input);
    }
    return unescaped;
}

private String unescapeId(String input) {
    // Regular expression to match escaped characters
    final String regex = "\\\\([^\\\\]+\\\\)(.*)";
    // Pattern object to maintain the regex
    Pattern p = Pattern.compile(regex);
    // Matcher object to match the regular expression
    Matcher m = p.matcher(input);
    // Initialize an empty string to store the unescaped output
    String output = "";
    while (m.find()) {
        // Check if the group contains an escaped character
        if (m.group(1) != null) {
            // Append the unescaped character to the output
            output += m.group(1).replace("\\", "");
        } else {
            // Append the remaining characters to the output
            output += m.group(2);
        }
    }
    // Return the unescaped output
    return output;
}

