    }

    return diffMappings;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    List<String> currentFields = mappings.getFieldsAsList();
    List<String> oldFields = getFieldsAsList(tableName);

    Map<String, String> newFieldsMap = new HashMap<>();
    Map<String, String> deprecatedFieldsMap = new HashMap<>();

    for (String currentField : currentFields) {
        if (!oldFields.contains(currentField)) {
            newFieldsMap.put(currentField, null);
        }
    }

    for (String oldField : oldFields) {
        if (!currentFields.contains(oldField)) {
            deprecatedFieldsMap.put(oldField, null);
        }
    }

    return new Mappings(newFieldsMap, deprecatedFieldsMap);
}

