    Map < String, FieldMappings > result = new HashMap < String, FieldMappings > ();

    for (String fieldName : fieldMappings.keySet()) {
        if (!fieldExists(tableName, fieldName)) {
            FieldMappings fieldMappings = this. getFieldMappings(tableName, fieldName);
            result.put(fieldName, fieldMappings);
        }
    }

    return new Mappings(result);
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Get the current mapping for the table
    Mappings currentMappings = getCurrentMappings(tableName);

    // Get the difference between the current mapping and the input mapping
    Mappings diffMappings = currentMappings.diff(mappings);

    // Remove _source from the diff mapping to avoid current index update conflict
    diffMappings.setSource(null);

    return diffMappings;
}

public Mappings diffStructure(String tableName, Mappings mappings) {

Mappings result = new Mappings();

Map<String, Mapping> currentMappings = mappings.getMappings().get(tableName);
Map<String, Object> currentSourceConfig = mappings.getSources().get(tableName);

for (Map.Entry<String, Mapping> entry : currentMappings.entrySet()) {

String fieldName = entry.getKey();
Mapping fieldMapping = entry.getValue();
if (!result.getMappings().containsKey(fieldName)) {
result.getMappings().put(fieldName, fieldMapping);
}
}

// Don't return _source config to avoid current index update conflict
if (result.getSources().containsKey(tableName) && currentSourceConfig != null) {
result.getSources().remove(tableName);
}

return result;
