    return timeBucket - (timeBucket % dayStep) + 1;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int bucketValue = (int) (timeBucket % 100);
    int year = (int) (timeBucket / 1000000);
    int month = (int) ((timeBucket / 10000) % 100);
    int day = (int) ((timeBucket / 100) % 100);
    int hour = (int) (timeBucket % 100);
    bucketValue = bucketValue - dayStep * 30;
    if (bucketValue < 0) {
        bucketValue = bucketValue + 30;
        day = day - 1;
        if (day < 0) {
            month = month - 1;
            if (month < 0) {
                year = year - 1;
                month = 11;
            }
            day = 28;
        }
    }
    return year * 1000000 + month * 10000 + day * 100 + hour;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    long revisedTimeBucket = timeBucket;
    int tempDayStep = dayStep;
    while (tempDayStep > 0) {
        if ((revisedTimeBucket % 1000000) < tempDayStep) {
            revisedTimeBucket -= ((revisedTimeBucket % 1000000) - tempDayStep);
            tempDayStep = 0;
        } else {
            revisedTimeBucket -= tempDayStep;
            tempDayStep = 0;
        }
    }
    return revisedTimeBucket;
}

