            int threadStartIdx = (int) threadData.startIdx;
            int threadEndIdx = (int) threadData.endIdx;
            // Check if the thread is in the specified time range
            boolean isThreadInRange = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (timeRange.getStartTime() <= threadStartIdx && threadEndIdx <= timeRange.getEndTime()) {
                    isThreadInRange = true;
                    break;
                }
            }
            // Add the snapshot if the thread is in the specified time range
            if (isThreadInRange) {
                ThreadSnapshot threadSnapshot = new ThreadSnapshot(isAlive, threadStartIdx, threadEndIdx);
                snapshots.add(threadSnapshot);
            }
        }
    }

    return snapshots;
}

