public static int computeUTF8Size(CharSequence str, int index, int len) {
    int size = 0;
    int strLen = str.length();
    for (int i = index; i < len; i++) {
        char c = str.charAt(i);
        if (c >= 1 && c <= 127) {
            size += 1;
        } else if (c <= 2047) {
            size += 2;
        } else {
            size += 3;
        }
    }
    return size;
}

