result |= ((long) b & 0x7F) << shift;
if ((b & 0x80) == 0) {
return result;
}
shift += 7;
}
}
}

public int readTag() throws IOException {
    // Read a field tag from the input stream
    int tag = inputStream.readInt();

    // Check if we have reached the end of the stream
    if (tag == 0) {
        return 0;
    }

    // Check if the tag is valid
    if (tag <= 0 || tag > MAX_FIELD_NUMBER) {
        throw new IOException("Invalid field tag: " + tag);
    }

    return tag;
}

public int readTag() throws IOException {
    int tag = 0;
    while (tag == 0) {
        tag = in.readVarint();
    }
    return tag;
}

public int readTag() throws IOException {
    return in.readInt32();
